```java
import java.util.HashMap;

public class BadUsage {
    public static void main(String[] args) {
        // Create an insecure Hashmap
        HashMap<String, Object> insecureMap = new HashMap<>();
        // Misuse of get and put instead of putIfAbsent
        // Security issues here...
        insecureMap.put("key", "value"); // Vulnerable

        // Accessing sensitive data without proper validation
        String sensitiveData = insecureMap.get("key"); // Vulnerable

        // Proper usage of HashMap
        HashMap<String, Object> secureMap = new HashMap<>();
        secureMap.put("key", "value");
